import { useStore } from "./store";
import { useShallow } from "zustand/shallow"; 
import { useState } from "react";

const selector = (s) => ({ nodes: s.nodes, edges: s.edges });

export const SubmitButton = () => {
  const { nodes, edges } = useStore(useShallow(selector)); 
  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    setLoading(true);
    try {
      const res = await fetch("http://localhost:8000/pipelines/parse", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ nodes, edges }),
      });
      const data = await res.json();
      const dagMsg = data.is_dag
        ? "✅ Valid DAG"
        : "⚠️ Not a DAG (contains cycles)";
      alert(
        `Pipeline Analysis\n\nNodes: ${data.num_nodes}\nEdges: ${data.num_edges}\nStructure: ${dagMsg}`,
      );
    } catch (err) {
      alert("Error connecting to backend. Make sure the server is running.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      style={{
        display: "flex",
        justifyContent: "center",
        padding: "14px",
        background: "#0d0f14",
        borderTop: "1px solid #1e2333",
      }}
    >
      <button
        onClick={handleSubmit}
        disabled={loading}
        style={{
          background: loading
            ? "#2d3347"
            : "linear-gradient(135deg, #6366f1, #818cf8)",
          border: "none",
          borderRadius: "8px",
          padding: "10px 32px",
          color: "#fff",
          fontSize: "13px",
          fontWeight: 600,
          cursor: loading ? "not-allowed" : "pointer",
          letterSpacing: "0.04em",
          fontFamily: "'Space Mono', monospace",
          boxShadow: loading ? "none" : "0 4px 15px rgba(99,102,241,0.35)",
          transition: "all 0.2s",
        }}
      >
        {loading ? "Analyzing..." : "Submit Pipeline"}
      </button>
    </div>
  );
};
